param()

$ErrorActionPreference = "Stop"

function Decode-Utf8([string]$Base64) {
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Base64))
}

function Read-Utf8([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Missing required file: $Path"
    }
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Write-Utf8([string]$Path, [string]$Content) {
    $Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Content, $Utf8NoBom)
}

$RepoRoot = (Get-Location).Path
$StatusPath = Join-Path $RepoRoot "STATUS.md"
$AuditPath = Join-Path $RepoRoot "docs/rc022f_authored_values_audit.md"

if (Test-Path -LiteralPath $AuditPath) {
    throw "Audit document already exists: $AuditPath"
}

$Status = Read-Utf8 $StatusPath
$OpenF = Decode-Utf8 ""
$ClosedF = Decode-Utf8 ""
$NextG = Decode-Utf8 ""
$AuditDocument = Decode-Utf8 ""
$NextHeading = Decode-Utf8 "IyMg0KHQu9C10LTRg9GO0YnQsNGPINGA0LDQsdC+0YLQsA=="

$OpenIndex = $Status.IndexOf($OpenF, [System.StringComparison]::Ordinal)
if ($OpenIndex -lt 0) {
    throw "Open RC-022f status line not found"
}
if ($Status.IndexOf($OpenF, $OpenIndex + $OpenF.Length, [System.StringComparison]::Ordinal) -ge 0) {
    throw "Open RC-022f status line is not unique"
}
if ($Status.Contains("- RC-022f")) {
    throw "STATUS.md already contains a closed RC-022f entry"
}

$HeadingPattern = [regex]::new(
    "(?m)^" + [regex]::Escape($NextHeading) + "[ `t]*$"
)
$HeadingMatches = $HeadingPattern.Matches($Status)
if ($HeadingMatches.Count -ne 1) {
    throw "Expected exactly one next-work heading in STATUS.md, found $($HeadingMatches.Count)"
}

$Newline = "`n"
if ($Status.Contains("`r`n")) {
    $Newline = "`r`n"
}

$StatusUpdated = $HeadingPattern.Replace(
    $Status,
    [System.Text.RegularExpressions.MatchEvaluator]{
        param($Match)
        return $ClosedF + $Newline + $Newline + $Match.Value
    },
    1
)
$StatusUpdated = $StatusUpdated.Replace($OpenF, $NextG)

Write-Utf8 $AuditPath $AuditDocument
Write-Utf8 $StatusPath $StatusUpdated

Write-Host "Applied RC-022f production-authored-values audit."
Write-Host "Added:"
Write-Host "  docs/rc022f_authored_values_audit.md"
Write-Host "Updated:"
Write-Host "  STATUS.md"
Write-Host "Decision:"
Write-Host "  pipeline-specific authoring profiles"
Write-Host "Opened:"
Write-Host "  RC-022g"
Write-Host ""
Write-Host "Next:"
Write-Host "  git diff --check"
Write-Host "  git diff -- STATUS.md docs/rc022f_authored_values_audit.md"
